//#region src/components/dropdown-menu.ts
var DropdownMenu = {
	oninit: ({ state }) => {
		state.selectedIndex = -1;
	},
	oncreate: ({ attrs, state, dom }) => {
		if (attrs.isVisible) {
			const handleKeyDown = (e) => {
				if (!attrs.isVisible) return;
				switch (e.key) {
					case "ArrowDown":
						e.preventDefault();
						state.selectedIndex = Math.min(state.selectedIndex + 1, attrs.options.length - 1);
						m.redraw();
						break;
					case "ArrowUp":
						e.preventDefault();
						state.selectedIndex = Math.max(state.selectedIndex - 1, 0);
						m.redraw();
						break;
					case "Enter":
					case " ":
						e.preventDefault();
						if (state.selectedIndex >= 0 && state.selectedIndex < attrs.options.length) attrs.onSelect(attrs.options[state.selectedIndex]);
						break;
					case "Escape":
						e.preventDefault();
						attrs.onClose();
				}
			};
			document.addEventListener("keydown", handleKeyDown);
			dom._keydownHandler = handleKeyDown;
		}
	},
	onremove: ({ dom }) => {
		const handler = dom._keydownHandler;
		if (handler) document.removeEventListener("keydown", handler);
	},
	view: ({ attrs, state }) => {
		if (!attrs.isVisible || attrs.options.length === 0) return m("");
		let menuPosition = attrs.position;
		if (attrs.triggerElement) {
			const rect = attrs.triggerElement.getBoundingClientRect();
			menuPosition = {
				x: rect.left,
				y: rect.bottom + 4
			};
		}
		return m(".dropdown-menu-container", {
			style: {
				position: "fixed",
				left: `${menuPosition.x}px`,
				top: `${menuPosition.y}px`,
				zIndex: 1e3
			},
			onclick: (e) => {
				e.stopPropagation();
			}
		}, [m(".dropdown-backdrop", {
			onclick: (e) => {
				attrs.onClose();
			},
			oncontextmenu: (e) => {
				e.preventDefault();
				attrs.onClose();
			}
		}), m(".dropdown-menu-content", attrs.options.map((option, index) => {
			const isSelected = index === state.selectedIndex;
			return m(".dropdown-menu-item", {
				key: option.name,
				class: isSelected ? "selected" : "",
				onclick: (e) => {
					e.preventDefault();
					e.stopPropagation();
					attrs.onSelect(option);
				},
				onmouseenter: () => {
					state.selectedIndex = index;
					m.redraw();
				},
				onkeydown: (e) => {
					if (e.key === "Enter" || e.key === " ") {
						e.preventDefault();
						attrs.onSelect(option);
					}
				},
				tabindex: isSelected ? 0 : -1
			}, [
				m(".dropdown-menu-icon", { innerHTML: option.icon }),
				m(".dropdown-menu-label", option.title),
				option.shortcut && m(".dropdown-menu-shortcut", option.shortcut)
			]);
		}))]);
	}
};
